# --- Output Table (ringkas 32 data pertama) ---
print("\n================== Perbandingan Output Hardware vs Software (G_layer3) ==================")
print(f"{'Idx':>4} {'HW':>10} {'SW':>10} {'AbsErr':>10} {'%Err':>10}")
